function renderConversations(){const list=$('conversation-list');list.replaceChildren();if(!state.conversations.length)list.append(el('p','small',t('noConversations')));for(const c of state.conversations){const b=button(c.name,()=>openConversation(c.id),'conversation-item');b.replaceChildren(el('strong','',c.name),el('span','',c.context));b.setAttribute('aria-current',String(c.id===state.active));list.append(b);}$('chat-count').textContent=state.conversations.length;}
function renderChat(){const c=activeConversation();$('chat-empty').hidden=!!c;$('chat-content').hidden=!c;if(!c){$('messages').replaceChildren();$('partner-preferences').replaceChildren();$('chat-name').textContent='';$('chat-context').textContent='';renderGuides();return;}$('chat-name').textContent=c.name;$('chat-context').textContent=c.context;$('partner-preferences').replaceChildren(preferenceChips(c.partnerPreferences));$('close-chat').hidden=!!c.ended;$('message-form').hidden=!!c.ended;$('chat-status').textContent=c.ended?t('ended'):t('chatPrivacy');$('older-messages').hidden=!state.hasOlder;const box=$('messages'),atBottom=box.scrollHeight-box.scrollTop-box.clientHeight<70;box.replaceChildren();for(const m of state.messages){const mine=m.authorId===state.profile.id,item=el('div','message'+(mine?' mine':'')+(m.guideId?' reference':''));item.append(el('strong','small',mine?t('you'):c.name),el('p','',m.body));const g=guides.find(g=>g.id===m.guideId);if(g)item.append(guideCard(g,true));const time=el('time','',new Intl.DateTimeFormat(language==='zh'?'zh-CN':'en',{dateStyle:'short',timeStyle:'short'}).format(new Date(m.created)));time.dateTime=new Date(m.created).toISOString();item.append(time);box.append(item);}if(atBottom)box.scrollTop=box.scrollHeight;renderGuides();}
async function openConversation(id){if(state.active!==id){state.messages=[];state.hasOlder=false;}state.active=id;showView('conversations');await loadMessages(true);renderConversations();}
async function loadMessages(initial=false,older=false){const id=state.active,generation=authGeneration;if(!id)return;let query='';if(older&&state.messages.length)query='?before='+state.messages[0].id;else if(!initial&&state.messages.length)query='?after='+state.messages.at(-1).id;const r=await api('/conversations/'+id+'/messages'+query);if(state.active!==id||generation!==authGeneration)return;const c=activeConversation();if(c)c.ended=r.ended;const dedup=new Map([...state.messages,...r.messages].map(m=>[m.id,m]));state.messages=[...dedup.values()].sort((a,b)=>a.id-b.id);if(initial||older)state.hasOlder=r.hasMore;renderChat();if(query.startsWith('?after')&&r.hasMore)await loadMessages();}
async function loadQuestions(more=false){if(!state.profile)return;if(!more){state.questions=[];state.hasMore=false;renderQuestions();}const generation=authGeneration,member=state.profile.id,request=++questionRequest,filters=questionPath();try{const result=await api(questionPath(more));if(generation!==authGeneration||state.profile?.id!==member||request!==questionRequest||filters!==questionPath())return;state.questions=more?[...state.questions,...result.questions]:result.questions;state.hasMore=result.hasMore;renderQuestions();}catch(error){if(generation===authGeneration&&state.profile?.id===member&&request===questionRequest)throw error;}}
