async function loadBlocks(){const generation=authGeneration,member=state.profile?.id,r=await api('/blocks');if(generation!==authGeneration||state.profile?.id!==member)return;const box=$('blocked-list');box.replaceChildren();if(!r.blocks.length)box.append(el('p','small',t('noBlocks')));for(const p of r.blocks){const row=el('div','blocked-row');row.append(el('span','',p.name),button('unblock',async()=>{await api('/blocks/'+encodeURIComponent(p.id),'DELETE');features.invalidateTakeaways();await loadBlocks();await refresh();},'text-button'));box.append(row);}}
