function questionPath(more=false){const params=new URLSearchParams();if($('filter').value)params.set('topic',$('filter').value);const status=$('question-status').value;if(status==='awaiting')params.set('awaiting','1');else if(status)params.set('status',status);if(more&&state.questions.length){const last=state.questions.at(-1);params.set('before',last.created);params.set('beforeId',last.id);}return '/questions'+(params.size?'?'+params:'');}
